import csv

# Read input stops
with open('outputs/t05_clean_stops.csv', 'r') as f:
    stops = list(csv.DictReader(f))

# Read output
with open('outputs/t06_stop_service_intensity.csv', 'r') as f:
    output = list(csv.DictReader(f))

# Verify all stops are present
stop_ids_output = {row['stop_id'] for row in output}
stop_ids_input = {row['stop_id'] for row in stops}

if stop_ids_output == stop_ids_input:
    print('All stop_ids match!')
else:
    missing = stop_ids_input - stop_ids_output
    extra = stop_ids_output - stop_ids_input
    print(f'Missing: {missing}')
    print(f'Extra: {extra}')

# Verify column order matches
input_cols = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon']
output_cols = ['stop_id', 'stop_name', 'stop_lat', 'stop_lon', 'n_departures', 'n_routes', 'first_departure', 'last_departure']

for i, row in enumerate(output):
    for j, col in enumerate(input_cols):
        if row[col] != stops[i][col]:
            print(f'Mismatch for stop {row[\"stop_id\"]}, column {col}')
            break
    else:
        continue
    break
else:
    print('All stop_name, stop_lat, stop_lon match!')
